"""Pydantic schemas for LLM task outputs and errors."""

from __future__ import annotations

from pydantic import BaseModel, Field

# ---------------------------------------------------------------------------
# Task output schemas – every LLM task defines one
# ---------------------------------------------------------------------------


class CreditMemoOutput(BaseModel):
    """Structured credit memo generated by an LLM."""

    summary_en: str = Field(..., description="English executive summary (2-4 sentences)")
    summary_ur: str = Field(..., description="Urdu executive summary (2-4 sentences)")
    strengths: list[str] = Field(default_factory=list, description="Key strengths of the applicant")
    weaknesses: list[str] = Field(default_factory=list, description="Key weaknesses / risk factors")
    recommendation_rationale: str = Field(
        ..., description="Why the model/policy reached its recommendation"
    )
    fact_ids_cited: list[str] = Field(
        default_factory=list,
        description="IDs from facts bundle that were cited",
    )


class StatementExtractionOutput(BaseModel):
    """Structured extraction from a bank/wallet statement."""

    account_holder: str = Field(..., description="Account holder name")
    bank_name: str = Field(default="", description="Issuing bank name")
    account_number_masked: str = Field(
        default="", description="Masked account number (last 4 digits)"
    )
    currency: str = Field(default="PKR", description="Currency code")
    period_start: str = Field(default="", description="Statement period start (ISO date)")
    period_end: str = Field(default="", description="Statement period end (ISO date)")
    opening_balance_pkr: int = Field(default=0, description="Opening balance in PKR")
    closing_balance_pkr: int = Field(default=0, description="Closing balance in PKR")
    total_inflows_pkr: int = Field(default=0, description="Total inflows in PKR")
    total_outflows_pkr: int = Field(default=0, description="Total outflows in PKR")
    fact_ids_cited: list[str] = Field(
        default_factory=list,
        description="IDs from facts bundle that were cited",
    )


class AdvisorOutput(BaseModel):
    """Advisor response: actionable guidance for an applicant."""

    advice_en: str = Field(..., description="English advice paragraph")
    advice_ur: str = Field(..., description="Urdu advice paragraph")
    action_items: list[str] = Field(
        default_factory=list,
        description="Numbered action items the applicant should take",
    )
    fact_ids_cited: list[str] = Field(
        default_factory=list,
        description="IDs from facts bundle that were cited",
    )


# ---------------------------------------------------------------------------
# Registry mapping task name -> output schema class
# ---------------------------------------------------------------------------

TASK_SCHEMAS: dict[str, type[BaseModel]] = {
    "credit_memo": CreditMemoOutput,
    "statement_extraction": StatementExtractionOutput,
    "advisor": AdvisorOutput,
}


# ---------------------------------------------------------------------------
# Error types
# ---------------------------------------------------------------------------


class LLMError(Exception):
    """Base error for all LLM-related failures."""


class LLMParseError(LLMError):
    """LLM returned content that could not be parsed as the expected schema."""


class LLMGroundingError(LLMError):
    """LLM output contained numbers not found in the grounding bundle."""


class LLMTimeoutError(LLMError):
    """LLM call timed out."""


class LLMRateLimitError(LLMError):
    """LLM call hit rate limit."""
